endmodule

module top_module(input clk, input reset, input sig, output reg pulse);
  reg prev;
  always @(posedge clk) begin
    if (reset) begin
      prev <= 1'b0;
      pulse <= 1'b0;
    end else begin
      prev <= sig;
      pulse <= sig & ~prev;
    end
  end
endmodule

module top_module(input clk, input reset, input x, output z);
  localparam S0 = 2'd0, S1 = 2'd1, S10 = 2'd2, S101 = 2'd3;
  reg [1:0] state, next;
  always @(*) begin
    case (state)
      S0:   next = x ? S1 : S0;
      S1:   next = x ? S1 : S10;
      S10:  next = x ? S101 : S0;
      default: next = x ? S1 : S10;
    endcase
  end
  always @(posedge clk)
    if (reset) state <= S0;
    else state <= next;
  assign z = (state == S101);
endmodule

module top_module(input clk, input reset, output reg [3:0] q);
